	assert.Equal(t, "countStuff", data.ScopeMetrics[0].Metrics[0].Name)

	firstMetricData := data.ScopeMetrics[0].Metrics[0].Data
	sumData, isSum := firstMetricData.(metricdata.Sum[int64])
	if !isSum {
